      // Project 4: Agente Borrar OTs
      p4Cat: "Agent RPA · Automatización Mainframe · MAPI",
      p4Name: "Work Order Purge Agent · Unattended AS/400 RPA",
      p4Pitch: "Autonomous software robot built in PowerShell utilizing native 32-bit HLLAPI emulation libraries to automate the cancellation and purge lifecycle of Work Orders in corporate AS/400 ERP via email triggers.",
      p4Kpi1Num: "< 30 sec",
      p4Kpi1Lbl: "Execution time (vs 4-8 hrs before)",
      p4Kpi2Num: "0 errors",
      p4Kpi2Lbl: "Human deletion errors eliminated",
      p4Kpi3Num: "100% 24/7",
      p4Kpi3Lbl: "Zero dependence on IT shifts",
      p4Bullet1: "<strong>Native 5250 interaction via HLLAPI (pcshll32.dll):</strong> High-speed automation of IBM i green-screen sessions, managing credentials securely encrypted via Windows DPAPI.",
      p4Bullet2: "<strong>Intelligent email triage (Outlook MAPI):</strong> Continuous 60-second scanning with work-order regex patterns and duplicate detection logic to identify prior technician intervention.",
      p4Bullet3: "<strong>Isolated multi-session allocation:</strong> Scans and attaches to available session letters (B through H) in minimized background mode without disturbing active operator terminals.",
      p4Bullet4: "<strong>Reverse safe-deletion of print signatures:</strong> Validates job 'Active' status and conducts structured reverse-order purge with controlled confirmation prompts ('J') before cancelling the parent WO.",
      p4Bullet5: "<strong>Clean teardown and audit trail:</strong> Automated thread-preserving email replies via ReplyAll, releasing the mainframe terminal session (6xF3 + Option 24) to conserve terminal licenses.",
      p4Pipe1: "Outlook Polling", p4Pipe1Sub: "Continuous 60s MAPI inbox polling via Outlook COM automation",
      p4Pipe2: "Anti-Duplication Filter", p4Pipe2Sub: "Heuristic scan for manual IT staff replies to prevent collisions",
      p4Pipe3: "Isolated Session Allocation", p4Pipe3Sub: "Dynamic allocation of free session letters (B to H) in minimized window",
      p4Pipe4: "QINTER Auth", p4Pipe4Sub: "Bypasses PC5250 popups with DPAPI credentials and WScript",
      p4Pipe5: "DISO Menu Navigation", p4Pipe5Sub: "Self-healing traversal: Option 8 -> A -> 8 -> 4",
      p4Pipe6: "F4 Signature Inspection", p4Pipe6Sub: "Matrix character reading of green-screen rows for signatures 01, 02...",
      p4Pipe7: "Reverse Purge ('J')", p4Pipe7Sub: "Safe reverse-order deletion of signatures with 'Ja' confirmation",
      p4Pipe8: "Teardown & ReplyAll", p4Pipe8Sub: "Thread-preserving notification and terminal teardown (6xF3 + 24)",
      p4Mod1Title: "WO Regex & Action Verb Parser", p4Mod1Desc: "Matches expressions like 'delete', 'cancel', 'purge' and 6-digit work order numbers starting with 4 (49xxxx).",
      p4Mod2Title: "Native HLLAPI 32-bit Driver", p4Mod2Desc: "Direct interaction via pcshll32.dll controlling IBM Personal Communications (pcsws.exe) on Telnet port 23.",
      p4Mod3Title: "Algorithmic Decision Tree", p4Mod3Desc: "Smart triage: Case 1 (not found/already purged), Case 2/3 (active on press, warning email), Case 2A/3A (safe purge).",
      p4Mod4Title: "Windows DPAPI Secret Store", p4Mod4Desc: "Credentials securely encrypted by machine and user SID in credentials.xml with second-by-second agent_log.txt tracking.",
      p4DataMainframe: "<strong>AS/400 Mainframe (IBM i):</strong> QINTER subsystem, DISO ERP menus (8 DISO -> Orders A -> Reorg 8 -> Purge 4), Telnet port 23 socket (10.0.3.29).",
      p4DataLocal: "<strong>Local Files & Secrets:</strong> <code>credentials.xml</code> (DPAPI encryption), <code>agent_log.txt</code> (real-time audit trail).",
      p4DataProtocols: "<strong>Libraries & Automation:</strong> PowerShell 5.1 Orchestrator, <code>pcshll32.dll</code> HLLAPI, IBM PCOMM (<code>pcsws.exe</code>), Outlook COM (MAPI).",

